        SIMD<UInt8>.repeating(26)
    )
    unsafe result.pointee = SIMD<UInt8>.selecting(
        SIMD<UInt8>.lessThan(letters, SIMD<UInt8>.repeating(26)),
        letters,
        numbers
    )
}

